{
  "type_map": {},
  "constraints": [
    {
      "id": "R1",
      "category": "count_semantics",
      "alternatives": [
        "df['sloss'] <= df['spkts']"
      ],
      "features": ["sloss", "spkts"],
      "rationale": "sloss counts retransmitted or dropped source packets, which is a subset of all source packets sent (spkts), so it cannot exceed spkts."
    },
    {
      "id": "R2",
      "category": "count_semantics",
      "alternatives": [
        "df['dloss'] <= df['dpkts']"
      ],
      "features": ["dloss", "dpkts"],
      "rationale": "dloss counts retransmitted or dropped destination packets, which is a subset of all destination packets sent (dpkts), so it cannot exceed dpkts."
    },
    {
      "id": "R3",
      "category": "count_semantics",
      "alternatives": [
        "(df['service'] == 'http') | (df['trans_depth'] == 0)"
      ],
      "features": ["service", "trans_depth"],
      "rationale": "trans_depth measures pipelined HTTP request/response depth, so it must be zero for non-HTTP flows."
    },
    {
      "id": "R4",
      "category": "count_semantics",
      "alternatives": [
        "(df['service'] == 'http') | (df['response_body_len'] == 0)"
      ],
      "features": ["service", "response_body_len"],
      "rationale": "response_body_len is the uncompressed content size of data from the server's HTTP service, so it must be zero for non-HTTP flows."
    },
    {
      "id": "R5",
      "category": "count_semantics",
      "alternatives": [
        "(df['service'] == 'ftp') | (df['is_ftp_login'] == 0)"
      ],
      "features": ["service", "is_ftp_login"],
      "rationale": "is_ftp_login indicates whether an FTP session was accessed with user and password, so it must be 0 for non-FTP flows."
    },
    {
      "id": "R6",
      "category": "count_semantics",
      "alternatives": [
        "(df['service'] == 'ftp') | (df['ct_ftp_cmd'] == 0)"
      ],
      "features": ["service", "ct_ftp_cmd"],
      "rationale": "ct_ftp_cmd counts flows with a command in an FTP session, so it must be 0 for non-FTP flows."
    },
    {
      "id": "R7",
      "category": "count_semantics",
      "alternatives": [
        "(df['service'] == 'http') | (df['ct_flw_http_mthd'] == 0)"
      ],
      "features": ["service", "ct_flw_http_mthd"],
      "rationale": "ct_flw_http_mthd counts flows with HTTP methods like GET or POST, so it must be 0 for non-HTTP flows."
    }
  ]
}
